impl Solution {
    pub fn minimum_abs_difference(mut arr: Vec<i32>) -> Vec<Vec<i32>> {
        arr.sort();
        let n = arr.len();

        let mut mi = i32::MAX;
        for i in 1..n {
            mi = mi.min(arr[i] - arr[i - 1]);
        }

        let mut ans = Vec::new();
        for i in 1..n {
            if arr[i] - arr[i - 1] == mi {
                ans.push(vec![arr[i - 1], arr[i]]);
            }
        }

        ans
    }
}

package leetcode_solutions_golang

import (
	"math"
	"sort"
)

//https://leetcode.com/problems/minimum-absolute-difference/
func minimumAbsDifference(arr []int) [][]int {
	minAbs := 3000000
	sort.Ints(arr)
	for i := 1; i < len(arr); i++ {
		curAbs := math.Abs(float64(arr[i] - arr[i-1]))
		minAbs = int(math.Min(float64(minAbs), curAbs))
	}
	result := [][]int{}
	for i := 1; i < len(arr); i++ {
		curAbs := int(math.Abs(float64(arr[i] - arr[i-1])))
		if curAbs == minAbs {
			result = append(result, []int{arr[i-1], arr[i]})
		}
	}
	return result
}
